1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials",
24	        expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
25	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
26	    @Mapping(target = "membershipTier", expression = "java(membershipTier(owner))")
27	    @Mapping(target = "locality", expression = "java(Locality.of(owner.getCity()))")
28	    OwnerDto toOwnerDto(Owner owner);
29	
30	    /** 'SILVER' when namesakeCount is 0 and an email is present, otherwise 'BRONZE'. */
31	    default String membershipTier(Owner owner) {
32	        boolean silver = Integer.valueOf(0).equals(owner.getNamesakeCount()) && owner.getEmail() != null;
33	        return silver ? "SILVER" : "BRONZE";
34	    }
35	
36	    /** '&lt;customerCode&gt;-M&lt;YY&gt;', YY = last two digits of the registrationDate year; null when either input is absent. */
37	    default String membershipNumber(Owner owner) {
38	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
39	            return null;
40	        }
41	        return owner.getCustomerCode() + "-M" + String.format("%02d", owner.getRegistrationDate().getYear() % 100);
42	    }
43	
44	    Owner toOwner(OwnerDto ownerDto);
45	
46	    @Mapping(target = "id", ignore = true)
47	    @Mapping(target = "pets", ignore = true)
48	    Owner toOwner(OwnerFieldsDto ownerDto);
49	
50	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
51	
52	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
53	
54	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
55	        OwnerPageDto ownerPageDto = new OwnerPageDto();
56	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
57	        ownerPageDto.setPage(ownerPage.getNumber());
58	        ownerPageDto.setSize(ownerPage.getSize());
59	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
60	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
61	        return ownerPageDto;
62	    }
63	}
