1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	
9	/**
10	 * Ensures the effective registration date falls on a business day: a Saturday or Sunday rolls
11	 * forward to the next Monday. Runs after {@code BuildOwner} has resolved the date (supplied in the
12	 * request or defaulted to today) and before any step reads it, so every value derived from it — the
13	 * membership number's year segment and the daily create-limit count — uses the adjusted date.
14	 */
15	public class AdjustOwnerRegistrationDate {
16	
17	    public void service(@Val Owner owner) {
18	        LocalDate date = owner.getRegistrationDate();
19	        DayOfWeek day = date.getDayOfWeek();
20	        if (day == DayOfWeek.SATURDAY) {
21	            owner.setRegistrationDate(date.plusDays(2));
22	        }
23	        else if (day == DayOfWeek.SUNDAY) {
24	            owner.setRegistrationDate(date.plusDays(1));
25	        }
26	    }
27	}
