1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
6	
7	/**
8	 * On create, rewrites the telephone into E.164 form. A leading '+' keeps the given
9	 * country code; otherwise '+61' is assumed and a single leading '0' is dropped from the
10	 * national digits. Spaces, dashes and brackets are stripped, and 8 to 15 digits must
11	 * follow the '+'. Mutates the built {@link Owner} in place so later steps store and
12	 * return the E.164 value.
13	 */
14	public class NormalizeOwnerTelephone {
15	
16	    public void service(@Val Owner owner) throws InvalidTelephoneException {
17	        String raw = owner.getTelephone() == null ? "" : owner.getTelephone().trim();
18	        String digits = raw.replaceAll("[^0-9]", "");
19	        String e164;
20	        if (raw.startsWith("+")) {
21	            e164 = "+" + digits;
22	        } else {
23	            e164 = "+61" + (digits.startsWith("0") ? digits.substring(1) : digits);
24	        }
25	        int count = e164.length() - 1;
26	        if (count < 8 || count > 15) {
27	            throw new InvalidTelephoneException("Telephone cannot form a valid E.164 number");
28	        }
29	        owner.setTelephone(e164);
30	    }
31	}
