1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	
8	/**
9	 * On create, rewrites the address into a canonical form: whitespace is trimmed and
10	 * collapsed to single spaces, letters are upper-cased, and common abbreviations are
11	 * expanded (ST-&gt;STREET, RD-&gt;ROAD, AVE-&gt;AVENUE). Mutates the built {@link Owner} in
12	 * place so later steps store, compare and return the normalized value. A blank input is
13	 * already rejected as a required field before this step runs.
14	 */
15	public class NormalizeOwnerAddress {
16	
17	    private static final Map<String, String> ABBREVIATIONS = Map.of(
18	            "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
19	
20	    public void service(@Val Owner owner) {
21	        String raw = owner.getAddress() == null ? "" : owner.getAddress();
22	        StringBuilder normalized = new StringBuilder();
23	        for (String token : raw.trim().split("\\s+")) {
24	            if (token.isEmpty()) {
25	                continue;
26	            }
27	            String upper = token.toUpperCase();
28	            if (normalized.length() > 0) {
29	                normalized.append(' ');
30	            }
31	            normalized.append(ABBREVIATIONS.getOrDefault(upper, upper));
32	        }
33	        owner.setAddress(normalized.toString());
34	    }
35	}
