1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Objects;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
9	
10	/**
11	 * On create, rejects the owner when its normalized telephone already belongs to another
12	 * owner. Runs after {@code NormalizeOwnerTelephone}, so the built owner already holds its
13	 * 10-digit value; each stored telephone is normalized the same way before comparison.
14	 */
15	public class EnsureUniqueOwnerTelephone {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
18	            throws DuplicateTelephoneException {
19	        String telephone = digits(owner.getTelephone());
20	        for (Owner existing : ownerRepository.findAll()) {
21	            if (!Objects.equals(existing.getId(), owner.getId())
22	                    && telephone.equals(digits(existing.getTelephone()))) {
23	                throw new DuplicateTelephoneException("Telephone is already used by another owner");
24	            }
25	        }
26	    }
27	
28	    private static String digits(String telephone) {
29	        return telephone == null ? "" : telephone.replaceAll("\\D", "");
30	    }
31	}
