1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Objects;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;
9	
10	/**
11	 * On create, rejects the owner when its city already contains 50 or more owners (compared
12	 * case-insensitively with collapsed whitespace).
13	 */
14	public class EnsureCityHasCapacity {
15	
16	    private static final int CAPACITY = 50;
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
19	            throws CityAtCapacityException {
20	        String city = normalize(owner.getCity());
21	        long count = 0;
22	        for (Owner existing : ownerRepository.findAll()) {
23	            if (!Objects.equals(existing.getId(), owner.getId())
24	                    && city.equals(normalize(existing.getCity()))) {
25	                count++;
26	            }
27	        }
28	        if (count >= CAPACITY) {
29	            throw new CityAtCapacityException("This city already has the maximum number of owners");
30	        }
31	    }
32	
33	    private static String normalize(String value) {
34	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
35	    }
36	}
