3	import java.time.LocalDate;
4	import java.util.Objects;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	import org.springframework.samples.petclinic.rest.escalation.DailyRegistrationLimitException;
10	
11	/**
12	 * On create, rejects the owner when 100 or more owners have already been registered today
13	 * (compared by registrationDate).
14	 */
15	public class EnsureDailyRegistrationCapacity {
16	
17	    private static final int DAILY_LIMIT = 100;
18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
20	            throws DailyRegistrationLimitException {
21	        LocalDate today = owner.getRegistrationDate();
22	        long count = 0;
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (!Objects.equals(existing.getId(), owner.getId())
25	                    && today.equals(existing.getRegistrationDate())) {
26	                count++;
27	            }
28	        }
29	        if (count >= DAILY_LIMIT) {
30	            throw new DailyRegistrationLimitException("The maximum number of owners for today has been reached");
31	        }
32	    }
33	}
