1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * On create, assigns the owner's {@code customerCode} as '&lt;CITY3&gt;-&lt;LAST3&gt;-&lt;NNNN&gt;', where
9	 * CITY3 is the upper-cased first three letters of the city, LAST3 the upper-cased first three of the last
10	 * name and NNNN a per-city 4-digit zero-padded sequence equal to one more than the owners already in that
11	 * city (e.g. 'LON-SMI-0007'). Runs before {@code SaveOwner} so the not-yet-persisted owner is excluded
12	 * from the count.
13	 */
14	public class AssignOwnerCustomerCode {
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
17	        String city = owner.getCity() == null ? "" : owner.getCity();
18	        int sequence = 1;
19	        for (Owner existing : ownerRepository.findAll()) {
20	            if (city.equals(existing.getCity())) {
21	                sequence++;
22	            }
23	        }
24	        owner.setCustomerCode(String.format("%s-%s-%04d", first3(city), first3(owner.getLastName()), sequence));
25	    }
26	
27	    private static String first3(String value) {
28	        String text = value == null ? "" : value;
29	        return text.substring(0, Math.min(3, text.length())).toUpperCase();
30	    }
31	}
